package rev

import "testing"

func TestReverse(t *testing.T) {
	if got := Reverse("abc"); got != "cba" {
		t.Errorf("Reverse = %q, want %q", got, "cba")
	}
	if got := Reverse(""); got != "" {
		t.Errorf("Reverse(empty) = %q", got)
	}
}

