package buf

// Buffer holds a rolling series of samples.
type Buffer struct{ xs []float64 }

func (b *Buffer) Append(x float64) { b.xs = append(b.xs, x) }

// Window returns the most recent n samples.
func (b *Buffer) Window(n int) []float64 {
	if n > len(b.xs) {
		n = len(b.xs)
	}
	return b.xs[len(b.xs)-n:]
}

