package store

import "errors"

var ErrReadOnly = errors.New("store is read-only")

type Store interface {
	Get(k string) (string, bool)
	Put(k, v string) error
}

type ReadOnlyStore struct{ M map[string]string }

func (s *ReadOnlyStore) Get(k string) (string, bool) { v, ok := s.M[k]; return v, ok }

files.store_test.go:
package store

import "testing"

func TestReadOnlyStoreSatisfiesStore(t *testing.T) {
	var s Store = &ReadOnlyStore{M: map[string]string{"a": "1"}}
	if v, ok := s.Get("a"); !ok || v != "1" {
		t.Fatalf("Get = %q %v", v, ok)
	}
	if err := s.Put("b", "2"); err == nil {
		t.Fatal("Put on a read-only store must return an error")
	}
}

